<script type="text/x-template" id="v-cheque-customer-picker-template">
<div><label for="cheque-customer-search">@lang('customer::cheques.customer')</label><input type="hidden" name="customer_id" :value="selected" required><input id="cheque-customer-search" class="mt-2 block w-full rounded border p-2 dark:bg-gray-900" type="search" v-model="query" @input="search" autocomplete="off" :placeholder="@js(trans('customer::cheques.choose'))"><ul class="mt-2 max-h-48 overflow-auto rounded border" v-if="results.length"><li v-for="customer in results" :key="customer.id"><button class="w-full p-3 text-start hover:bg-gray-100" type="button" @click="choose(customer)">@{{ customer.first_name }} @{{ customer.last_name }} — @{{ customer.phone }}</button></li></ul><small v-if="selected">#@{{ selected }}</small></div>
</script>
<script type="module">
app.component('v-cheque-customer-picker',{template:'#v-cheque-customer-picker-template',props:['initialId','initialCustomer'],data(){return{selected:this.initialId||'',query:this.initialCustomer?`${this.initialCustomer.first_name} ${this.initialCustomer.last_name} — ${this.initialCustomer.phone||''}`:'',results:[],timer:null,version:0};},methods:{search(){clearTimeout(this.timer);this.selected='';const version=++this.version;if(this.query.length<2){this.results=[];return;}this.timer=setTimeout(async()=>{try{const url=new URL(@json(route('admin.customers.cheques.customers')));url.searchParams.set('q',this.query);const response=await fetch(url,{headers:{Accept:'application/json'}});if(response.ok&&version===this.version)this.results=await response.json();}catch{this.results=[];}},250);},choose(customer){this.selected=customer.id;this.query=`${customer.first_name} ${customer.last_name} — ${customer.phone||''}`;this.results=[];this.version++;}},beforeUnmount(){clearTimeout(this.timer);this.version++;}});
</script>
